  },
  {
    "file": "backend/src/main/java/com/cc91/service/CommentService.java",
    "line": 263,
    "summary": "toCommentResponse() individually queries userProfileRepository.findByUserId() for every comment, but buildCommentTree() immediately overwrites the result from the batch avatarMap — N wasted DB queries per request",
    "failure_scenario": "Post with 50 comments → 50 individual SELECT queries on user_profiles, all results thrown away because lines 219-220 overwrite from the batch map"
  },
